"""Private subprocess worker. Attachment paths are generated by extraction.py only."""
from __future__ import annotations

import ctypes
import errno
import io
import json
import os
from pathlib import Path, PurePosixPath
import re
import resource
import shutil
import stat
import struct
import sys
import urllib.parse
from xml.parsers import expat
import xml.etree.ElementTree as ET
import zipfile

# The worker runs with -I; load only the trusted sibling, without package startup.
sys.path.insert(0, str(Path(__file__).resolve().parent))
from extraction import (Extraction, ExtractionFailure, MAX_INPUT_BYTES, MAX_TEXT_CHARS,
                        result_json, run_bounded)


MAX_MEMBERS = 256
MAX_MEMBER_BYTES = 8 * 1024 * 1024
MAX_EXPANDED_BYTES = 32 * 1024 * 1024
MAX_RATIO = 200
MAX_PAGES = 8
MAX_PIXELS = 20_000_000
NS_W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
NS_S = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
NS_A = "http://schemas.openxmlformats.org/drawingml/2006/main"
NS_P = "http://schemas.openxmlformats.org/presentationml/2006/main"
NS_R = "http://schemas.openxmlformats.org/package/2006/relationships"


def fail(status: str, reason: str):
    raise ExtractionFailure(status, reason)


def sandbox():
    """Fail closed if Linux limits or the inherited no-network filter cannot load."""
    os.umask(0o077)
    for name, value in ((resource.RLIMIT_AS, 768 * 1024 * 1024),
                        (resource.RLIMIT_CPU, 20), (resource.RLIMIT_FSIZE, 24 * 1024 * 1024),
                        (resource.RLIMIT_NOFILE, 64), (resource.RLIMIT_CORE, 0),
                        (resource.RLIMIT_STACK, 16 * 1024 * 1024)):
        resource.setrlimit(name, (value, value))
    library = ctypes.CDLL("libseccomp.so.2", use_errno=True)
    library.seccomp_init.argtypes = [ctypes.c_uint32]
    library.seccomp_init.restype = ctypes.c_void_p
    library.seccomp_syscall_resolve_name.argtypes = [ctypes.c_char_p]
    library.seccomp_syscall_resolve_name.restype = ctypes.c_int
    library.seccomp_rule_add.argtypes = [ctypes.c_void_p, ctypes.c_uint32, ctypes.c_int, ctypes.c_uint]
    library.seccomp_load.argtypes = [ctypes.c_void_p]
    library.seccomp_release.argtypes = [ctypes.c_void_p]
    context = library.seccomp_init(0x7FFF0000)  # SCMP_ACT_ALLOW
    if not context:
        fail("unsupported", "Linux seccomp network isolation unavailable")
    try:
        for name in ("socket", "socketpair", "connect", "bind", "listen", "accept", "accept4",
                     "sendto", "sendmsg", "recvfrom", "recvmsg", "socketcall", "ptrace",
                     "process_vm_readv", "process_vm_writev", "mount", "bpf", "io_uring_setup"):
            number = library.seccomp_syscall_resolve_name(name.encode())
            if number >= 0 and library.seccomp_rule_add(context, 0x00050000 | errno.EPERM, number, 0):
                fail("unsupported", "Linux seccomp network isolation unavailable")
        if library.seccomp_load(context):
            fail("unsupported", "Linux seccomp network isolation unavailable")
    finally:
        library.seccomp_release(context)


def tool(name: str, args: list[str], workdir: Path, *, limit=512 * 1024, timeout=12,
         input_data: bytes | None = None) -> bytes:
    binary = shutil.which(name, path="/usr/bin:/bin")
    if not binary:
        fail("unsupported", f"required local tool unavailable: {name}")
    code, output, errors = run_bounded([binary, *args], cwd=workdir, timeout=timeout,
                                        output_limit=limit, input_data=input_data)
    if code:
        # Parser diagnostics can contain attachment text. Never return or log them.
        if b"password" in errors.lower() or b"encrypted" in errors.lower():
            fail("unreadable", "password-protected/encrypted attachment")
        if code < 0:
            fail("unreadable", f"{name} stopped or exceeded a resource limit")
        fail("unreadable", f"{name} rejected malformed or unreadable content")
    return output


def bounded_text(parts) -> str:
    pieces, size = [], 0
    for part in parts:
        size += len(part) + 1
        if size > MAX_TEXT_CHARS:
            fail("dangerous", "extracted text limit exceeded (65536 characters)")
        pieces.append(part)
    # Remove NUL/C0 controls; caller still must treat remaining text as untrusted.
    return re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", "", "\n".join(pieces)).strip()


def safe_xml(raw: bytes) -> ET.Element:
    """Expat detects DTDs in every XML encoding before ElementTree sees content."""
    parser = expat.ParserCreate()
    def reject(*args):
        fail("dangerous", "XML DTD/entity declarations are forbidden")
    parser.StartDoctypeDeclHandler = reject
    parser.EntityDeclHandler = reject
    parser.ExternalEntityRefHandler = reject
    parser.Parse(raw, True)
    return ET.fromstring(raw)


def _zip_members(data: bytes) -> dict[str, bytes]:
    members: dict[str, bytes] = {}
    with zipfile.ZipFile(io.BytesIO(data)) as archive:
        infos = archive.infolist()
        if len(infos) > MAX_MEMBERS:
            fail("dangerous", "ZIP member count limit exceeded (256)")
        total = 0
        for info in infos:
            name = info.filename
            path = PurePosixPath(name)
            if (name in members or name.startswith("/") or "\\" in name or ":" in name
                    or "\0" in name or any(p in {"..", ".", ""} for p in name.rstrip("/").split("/"))
                    or stat.S_ISLNK(info.external_attr >> 16)):
                fail("dangerous", "unsafe or duplicate ZIP member path")
            if info.flag_bits & 1:
                fail("unreadable", "password-protected/encrypted Office package")
            if info.compress_type not in {zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED}:
                fail("unsupported", "unsupported Office ZIP compression")
            total += info.file_size
            if (info.file_size > MAX_MEMBER_BYTES or total > MAX_EXPANDED_BYTES
                    or info.file_size > max(info.compress_size, 1) * MAX_RATIO):
                fail("dangerous", "ZIP decompression/size limit exceeded")
            lower = name.lower()
            if (any(p.lower() in {"embeddings", "activex", "customui", "externallinks"} for p in path.parts)
                    or lower.endswith((".bin", ".exe", ".js", ".vbs", ".zip", ".ole", ".html", ".svg"))
                    or "vbaproject" in lower or "macrosheet" in lower):
                fail("dangerous", "Office macro, active content or embedded package detected")
            with archive.open(info) as stream:
                raw = stream.read(MAX_MEMBER_BYTES + 1)
                if len(raw) != info.file_size or len(raw) > MAX_MEMBER_BYTES:
                    fail("dangerous", "ZIP member expansion exceeds declared size")
                members[name] = raw
    return members


def _scan_office(members: dict[str, bytes]) -> dict[str, ET.Element]:
    xml = {}
    for name, raw in members.items():
        if name.lower().endswith((".xml", ".rels")):
            root = safe_xml(raw)
            xml[name] = root
            for element in root.iter():
                local = element.tag.rsplit("}", 1)[-1].lower()
                if local in {"altchunk", "oleobject", "object", "control", "ddelink", "ddeitem",
                             "externalreference", "externalbook", "attachedtemplate"}:
                    fail("dangerous", "Office active/embedded or externally linked content detected")
                if local in {"instrtext", "fldsimple"}:
                    # Never evaluate fields, including INCLUDETEXT, DDE and remote pictures.
                    fail("dangerous", "Office dynamic field detected")
                if local == "f":
                    formula = (element.text or "").upper()
                    if any(token in formula for token in ("DDE", "WEBSERVICE", "HYPERLINK", "RTD(", "|", "[", "CALL(", "REGISTER")):
                        fail("dangerous", "potentially active/external spreadsheet formula detected")
                if local == "override" or local == "default":
                    mime = element.attrib.get("ContentType", "").lower()
                    if any(token in mime for token in ("macroenabled", "vbaproject", "activex", "oleobject")):
                        fail("dangerous", "Office active content type detected")
                if element.tag == f"{{{NS_R}}}Relationship":
                    target = urllib.parse.unquote(element.attrib.get("Target", ""))
                    reltype = element.attrib.get("Type", "").rsplit("/", 1)[-1]
                    if any(token in reltype.lower() for token in ("oleobject", "package", "vbaproject", "control", "attachedtemplate")):
                        fail("dangerous", "Office active relationship detected")
                    external = element.attrib.get("TargetMode", "").lower() == "external"
                    if external or urllib.parse.urlsplit(target).scheme or target.startswith("//"):
                        # Passive hyperlinks are not followed or included in output.
                        if reltype != "hyperlink":
                            fail("dangerous", "Office external resource relationship detected")
    return xml


def _ordered_parts(xml: dict[str, ET.Element], main: str, tag: str, relation: str,
                   relpath: str, prefix: str) -> list[str]:
    """Use package order, not lexicographic slide10-before-slide2 ordering."""
    relationships = xml.get(relpath)
    if relationships is None:
        fail("unreadable", "Office part relationships missing")
    links = {el.attrib.get("Id"): el for el in relationships}
    result = []
    for element in xml[main].iter(tag):
        rid = element.attrib.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        link = links.get(rid)
        if link is None or not link.attrib.get("Type", "").endswith("/" + relation):
            fail("unreadable", "Office part relationship invalid")
        target = urllib.parse.unquote(link.attrib.get("Target", ""))
        # Canonicalise only package-internal paths; nothing is written to disk.
        parts = []
        for part in (target.lstrip("/") if target.startswith("/") else prefix + target).split("/"):
            if part == "..":
                if not parts:
                    fail("dangerous", "Office relationship escapes package")
                parts.pop()
            elif part not in {"", "."}:
                parts.append(part)
        name = "/".join(parts)
        if name not in xml:
            fail("unreadable", "Office referenced content missing")
        result.append(name)
    return result


def office_text(data: bytes, kind: str) -> str:
    members = _zip_members(data)
    xml = _scan_office(members)  # Scan every member before emitting any text.
    main = {"docx": "word/document.xml", "xlsx": "xl/workbook.xml", "pptx": "ppt/presentation.xml"}[kind]
    if main not in xml or "[Content_Types].xml" not in xml or "_rels/.rels" not in xml:
        fail("unreadable", "OOXML package missing required parts or format mismatch")
    if kind == "docx":
        if xml[main].tag != f"{{{NS_W}}}document":
            fail("unsupported", "unsupported Word XML namespace/variant")
        names = [main] + sorted(n for n in xml if n.startswith("word/") and re.search(r"/(header\d+|footer\d+|footnotes|endnotes)\.xml$", n))
        return bounded_text("".join(p.itertext()) if p.tag == f"{{{NS_W}}}t" else
                            "".join(t.text or "" for t in p.iter(f"{{{NS_W}}}t"))
                            for name in names for p in xml[name].iter(f"{{{NS_W}}}p"))
    if kind == "pptx":
        names = _ordered_parts(xml, main, f"{{{NS_P}}}sldId", "slide",
                               "ppt/_rels/presentation.xml.rels", "ppt/")
        return bounded_text(" ".join(t.text or "" for t in paragraph.iter(f"{{{NS_A}}}t"))
                            for name in names for paragraph in xml[name].iter(f"{{{NS_A}}}p"))
    names = _ordered_parts(xml, main, f"{{{NS_S}}}sheet", "worksheet",
                           "xl/_rels/workbook.xml.rels", "xl/")
    shared = xml.get("xl/sharedStrings.xml")
    strings = [] if shared is None else ["".join(t.text or "" for t in si.iter(f"{{{NS_S}}}t")) for si in shared]
    rows = []
    for name in names:
        for row in xml[name].iter(f"{{{NS_S}}}row"):
            values = []
            for cell in row.findall(f"{{{NS_S}}}c"):
                value = cell.findtext(f"{{{NS_S}}}v", "")
                celltype = cell.attrib.get("t")
                if celltype == "s":
                    index = int(value)
                    if index < 0 or index >= len(strings):
                        fail("unreadable", "invalid spreadsheet shared-string index")
                    value = strings[index]
                elif celltype == "inlineStr":
                    value = "".join(t.text or "" for t in cell.iter(f"{{{NS_S}}}t"))
                if cell.find(f"{{{NS_S}}}f") is not None and not value:
                    fail("unreadable", "spreadsheet formula has no cached value; formulas are never evaluated")
                values.append(f"{cell.attrib.get('r', '?')}: {value}")
            rows.append("\t".join(values))
    return bounded_text(rows)


PDF_DANGER = {"/JavaScript", "/JS", "/AA", "/OpenAction", "/Launch", "/EmbeddedFile",
              "/EmbeddedFiles", "/Filespec", "/RichMedia", "/XFA", "/SubmitForm",
              "/ImportData", "/GoToR", "/GoToE", "/Rendition", "/Sound", "/Movie", "/3D",
              "/AcroForm"}


def _pdf_scan(source: Path) -> list[bool]:
    raw = tool("qpdf", ["--json", "--json-stream-data=inline", "--decode-level=generalized", str(source)], source.parent,
               limit=48 * 1024 * 1024)
    document = json.loads(raw)
    if document.get("encrypt", {}).get("encrypted"):
        fail("unreadable", "password-protected/encrypted PDF")
    stack = [document.get("qpdf", [])]
    while stack:
        item = stack.pop()
        if isinstance(item, dict):
            if PDF_DANGER.intersection(item):
                fail("dangerous", "PDF active action, embedded file or executable feature detected")
            stack.extend(item.values())
        elif isinstance(item, list):
            stack.extend(item)
        elif isinstance(item, str) and item in PDF_DANGER:
            fail("dangerous", "PDF active action, embedded file or executable feature detected")
    pages = document.get("pages", [])
    if len(pages) > MAX_PAGES:
        fail("dangerous", "PDF page limit exceeded (8)")
    if not pages:
        fail("unreadable", "PDF contains no readable pages")
    return [bool(page.get("images")) for page in pages]


def ocr(source: Path) -> str:
    # stdin forces in-memory image decoding, avoiding Tesseract's file-list mode.
    return tool("tesseract", ["stdin", "stdout", "-l", "eng", "--psm", "6"],
                source.parent, limit=MAX_TEXT_CHARS * 4,
                input_data=source.read_bytes()).decode("utf-8", errors="replace").strip()


def pdf_text(source: Path) -> str:
    pages = _pdf_scan(source)
    output = []
    for page, has_images in enumerate(pages, 1):
        text = tool("pdftotext", ["-f", str(page), "-l", str(page), "-enc", "UTF-8",
                                   "-nopgbrk", str(source), "-"], source.parent,
                    limit=MAX_TEXT_CHARS * 4).decode("utf-8", errors="replace").strip()
        if not text or has_images:
            target = source.parent / "page"
            tool("pdftoppm", ["-f", str(page), "-l", str(page), "-singlefile", "-scale-to", "2400",
                              "-gray", "-png", str(source), str(target)], source.parent, limit=65536)
            image = target.with_suffix(".png")
            if not image.is_file() or image.stat().st_size > 24 * 1024 * 1024:
                fail("dangerous", "rendered image file limit exceeded")
            image_dimensions(image.read_bytes(), "png")
            recognised = ocr(image)
            image.unlink()
            if recognised and " ".join(recognised.split()) != " ".join(text.split()):
                text = text + "\n[OCR]\n" + recognised if text else recognised
        if not text:
            fail("unreadable", "PDF page has no extractable text; OCR returned no text")
        output.append(text)
        bounded_text(output)
    return bounded_text(output)


def image_dimensions(data: bytes, kind: str):
    """Small header checks before the decoder; decoder limits remain authoritative."""
    width = height = 0
    if kind == "png" and data.startswith(b"\x89PNG\r\n\x1a\n") and len(data) >= 33:
        if data[12:16] != b"IHDR":
            fail("unreadable", "invalid PNG header")
        width, height = struct.unpack(">II", data[16:24])
        if b"acTL" in data:
            fail("unsupported", "animated PNG is unsupported")
    elif kind == "jpeg" and data.startswith(b"\xff\xd8"):
        offset = 2
        while offset + 4 <= len(data):
            if data[offset] != 255:
                fail("unreadable", "invalid JPEG marker")
            marker = data[offset + 1]
            offset += 2
            if marker == 255:
                offset -= 1
                continue
            if marker in {0xD8, 0xD9} or 0xD0 <= marker <= 0xD7:
                continue
            length = int.from_bytes(data[offset:offset + 2], "big")
            if length < 2 or offset + length > len(data):
                fail("unreadable", "truncated JPEG segment")
            if marker in {0xC0, 0xC1, 0xC2} and length >= 7:
                height, width = struct.unpack(">HH", data[offset + 3:offset + 7])
                break
            if marker == 0xDA:
                break
            offset += length
    elif kind == "bmp" and data.startswith(b"BM") and len(data) >= 54:
        if int.from_bytes(data[14:18], "little") < 40:
            fail("unsupported", "legacy BMP header unsupported")
        width, height = struct.unpack("<ii", data[18:26])
        height = abs(height)
    elif kind == "tiff" and data[:4] in {b"II*\0", b"MM\0*"}:
        endian = "little" if data[:2] == b"II" else "big"
        offset = int.from_bytes(data[4:8], endian)
        if offset + 2 > len(data):
            fail("unreadable", "invalid TIFF directory")
        count = int.from_bytes(data[offset:offset + 2], endian)
        if count > 256 or offset + 2 + count * 12 + 4 > len(data):
            fail("dangerous", "TIFF directory limit/size invalid")
        for index in range(count):
            entry = data[offset + 2 + index * 12:offset + 14 + index * 12]
            tag, dtype = int.from_bytes(entry[:2], endian), int.from_bytes(entry[2:4], endian)
            if tag in {256, 257}:
                if int.from_bytes(entry[4:8], endian) != 1 or dtype not in {3, 4}:
                    fail("unsupported", "unsupported TIFF dimension encoding")
                value = int.from_bytes(entry[8:10] if dtype == 3 else entry[8:12], endian)
                if tag == 256:
                    width = value
                else:
                    height = value
        end = offset + 2 + count * 12
        if int.from_bytes(data[end:end + 4], endian):
            fail("unsupported", "multi-frame TIFF unsupported; convert pages individually")
    else:
        fail("unreadable", "image signature does not match supported format")
    if width <= 0 or height <= 0:
        fail("unreadable", "image dimensions missing or invalid")
    if width * height > MAX_PIXELS or max(width, height) > 10000:
        fail("dangerous", "image dimension/pixel limit exceeded (20 megapixels, 10000 per side)")


def process(kind: str, source: Path) -> Extraction:
    data = source.read_bytes()
    if len(data) > MAX_INPUT_BYTES:
        fail("dangerous", "attachment byte limit exceeded")
    if kind in {"docx", "xlsx", "pptx"}:
        text = office_text(data, kind)
    elif kind == "pdf":
        if not data.startswith(b"%PDF-"):
            fail("unreadable", "PDF signature mismatch")
        text = pdf_text(source)
    else:
        image_dimensions(data, kind)
        text = bounded_text([ocr(source)])
    if not text:
        fail("unreadable", "no extractable text; OCR may be empty, unavailable or unable to recognise this content")
    return Extraction("ok", text, "local extraction complete; untrusted text, detection is not a malware safety guarantee")


def main():
    try:
        sandbox()
        result = process(sys.argv[1], Path(sys.argv[2]))
    except ExtractionFailure as exc:
        result = Extraction(exc.status, reason=exc.reason)
    except (zipfile.BadZipFile, ET.ParseError, expat.ExpatError, ValueError, KeyError,
            IndexError, struct.error, OverflowError):
        result = Extraction("unreadable", reason="malformed or unsupported document structure")
    except (OSError, MemoryError, RuntimeError, RecursionError):
        result = Extraction("unreadable", reason="local parser/isolation unavailable or resource limit exceeded")
    print(result_json(result))


if __name__ == "__main__":
    main()
